-- Coach — NRC structure + higher volume (peak ~80km) + cross-training + strength & mobility.
-- Runs Mon/Wed/Thu/Sat/Sun; Tue/Fri = cross-training + strength+mobility. Idempotent.
delete from training_plan where day_date between '2026-06-01' and '2026-10-12';
on conflict (day_date, session_type) do update set title=excluded.title, planned_distance_km=excluded.planned_distance_km, planned_duration_min=excluded.planned_duration_min, target_pace=excluded.target_pace, details=excluded.details, coach_note=excluded.coach_note;
